INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c1-1000-0000-000000000009','B2','co_dialogue_c1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] Le communiqué de la préfecture évoque « une réorganisation des dispositifs d''accueil sans suppression de services ».
[Femme] La formule est habile : on parle de réorganisation, mais on promet de ne rien supprimer.
[Homme] Les associations, elles, hurlent à la fermeture déguisée.
[Femme] Et le préfet maintient sa formule au mot près à chaque interview.
[Homme] Où réside l''ambiguïté volontaire de cette communication ?
[Femme] ...

A. « Sans suppression de services » laisse entendre la continuité, alors qu''une réorganisation peut très bien fermer des sites tout en transférant la fonction.
B. La préfecture nie ouvertement les fermetures alors qu''elles sont publiquement actées.
C. Le communiqué oppose explicitement les inquiétudes des associations à celles des usagers.
D. Le mot « accueil » est utilisé dans son sens administratif strict, contraire au sens commun.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Le communiqué de la préfecture évoque « une réorganisation des dispositifs d''accueil sans suppression de services ».</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">La formule est habile : on parle de réorganisation, mais on promet de ne rien supprimer.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Les associations, elles, hurlent à la fermeture déguisée.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Et le préfet maintient sa formule au mot près à chaque interview.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Où réside l''ambiguïté volontaire de cette communication ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>« Sans suppression de services » laisse entendre la continuité, alors qu''une réorganisation peut très bien fermer des sites tout en transférant la fonction.<break time="700ms"/>B.<break time="300ms"/>La préfecture nie ouvertement les fermetures alors qu''elles sont publiquement actées.<break time="700ms"/>C.<break time="300ms"/>Le communiqué oppose explicitement les inquiétudes des associations à celles des usagers.<break time="700ms"/>D.<break time="300ms"/>Le mot « accueil » est utilisé dans son sens administratif strict, contraire au sens commun.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Cinq tours décortiquent une formule officielle qui résiste à la critique. La question demande **où se loge précisément l''ambiguïté linguistique** exploitée. Seule A repère la **distinction fonction/site** : promettre « pas de suppression de services » n''empêche pas de fermer des points d''accueil et de transférer la fonction ailleurs. B accuse la préfecture **de mensonge frontal** — ce que la femme dément (« la formule est habile », pas mensongère). C invente **une opposition d''acteurs** absente du communiqué. D propose **une ambiguïté lexicale** sur « accueil » qui n''est pas étayée par le dialogue.','[{"label": "A", "is_correct": true, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-DeniseNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.437065+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c1-1000-0000-00000000000a','B2','co_dialogue_c1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] On voit aujourd''hui des jeunes diplômés refuser des postes qu''on aurait acceptés sans réfléchir il y a vingt ans.
[Homme] Tu trouves cela problématique ?
[Femme] Ni problématique ni anodin. Cela me dit quelque chose de notre époque.
[Homme] Justement, qu''est-ce que cette attitude révèle, à l''aune de ce qu''on vivait nous-mêmes au même âge ?
[Femme] ...

A. Un manque flagrant de courage chez les nouvelles générations face à l''effort.
B. Un basculement : le travail n''est plus le centre légitime autour duquel on organise sa vie.
C. Une difficulté économique accrue qui pousse à attendre la meilleure offre possible.
D. Une méfiance compréhensible envers des employeurs jugés peu fiables.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">On voit aujourd''hui des jeunes diplômés refuser des postes qu''on aurait acceptés sans réfléchir il y a vingt ans.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tu trouves cela problématique ?</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Ni problématique ni anodin. Cela me dit quelque chose de notre époque.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Justement, qu''est-ce que cette attitude révèle, à l''aune de ce qu''on vivait nous-mêmes au même âge ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Un manque flagrant de courage chez les nouvelles générations face à l''effort.<break time="700ms"/>B.<break time="300ms"/>Un basculement : le travail n''est plus le centre légitime autour duquel on organise sa vie.<break time="700ms"/>C.<break time="300ms"/>Une difficulté économique accrue qui pousse à attendre la meilleure offre possible.<break time="700ms"/>D.<break time="300ms"/>Une méfiance compréhensible envers des employeurs jugés peu fiables.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','La femme refuse d''emblée la lecture morale (« ni problématique ni anodin ») et propose une lecture **générationnelle / sociologique**. La question demande **ce que ce comportement révèle de l''époque**, par contraste avec la génération précédente. Seule B nomme ce basculement de valeurs (place centrale du travail). A est précisément **la lecture morale** que la femme a déjà écartée — distracteur très fort. C donne **une explication conjoncturelle économique** (« pourquoi attendent-ils ? ») qui n''engage pas l''époque. D propose **une explication relationnelle** (méfiance), sans portée révélatrice.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": true, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-HenriNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.437065+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c1-1000-0000-00000000000b','B2','co_dialogue_c1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] La discussion avec Élise a commencé très cordialement, autour d''un café.
[Femme] Et pourtant, vous vous êtes quittés en froid, d''après ce que tu m''en dis.
[Homme] J''ai senti que le ton a basculé à un moment, sans que je puisse exactement le situer.
[Femme] Essaie de te rappeler : à quel moment le ton a-t-il basculé, précisément ?
[Homme] ...

A. Au moment précis où elle s''est levée pour partir, après notre dernière phrase.
B. Dès l''instant où nous nous sommes assis face à face, sans bavardage préalable.
C. Quand j''ai osé mentionner, en passant, le projet de promotion qu''elle convoitait aussi.
D. À la toute fin, lorsqu''elle a sèchement refusé que je règle son café.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">La discussion avec Élise a commencé très cordialement, autour d''un café.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Et pourtant, vous vous êtes quittés en froid, d''après ce que tu m''en dis.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">J''ai senti que le ton a basculé à un moment, sans que je puisse exactement le situer.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Essaie de te rappeler : à quel moment le ton a-t-il basculé, précisément ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Au moment précis où elle s''est levée pour partir, après notre dernière phrase.<break time="700ms"/>B.<break time="300ms"/>Dès l''instant où nous nous sommes assis face à face, sans bavardage préalable.<break time="700ms"/>C.<break time="300ms"/>Quand j''ai osé mentionner, en passant, le projet de promotion qu''elle convoitait aussi.<break time="700ms"/>D.<break time="300ms"/>À la toute fin, lorsqu''elle a sèchement refusé que je règle son café.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Le dialogue précise que la discussion **a commencé cordialement** et que la rupture s''est faite **insensiblement, en cours d''échange**. La question demande **le point de bascule pragmatique**, ni le début (réfuté), ni un signal terminal (qui en serait l''effet). Seule C désigne un déclencheur intermédiaire (mention d''un sujet sensible « en passant ») cohérent avec un glissement insensible. A et D désignent **des manifestations finales** du refroidissement — proches mais relèvent du symptôme, pas du basculement. B contredit **explicitement** le premier tour (« commencé cordialement »).','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": true, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-DeniseNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.437065+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c1-1000-0000-00000000000c','B2','co_dialogue_c1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] La majorité municipale a fini par voter le projet d''écoquartier.
[Homme] L''opposition s''y était farouchement opposée pendant six mois.
[Femme] Et pourtant, le vote est passé presque sans débat.
[Homme] Eu égard à cette volte-face, quelle contrepartie inavouée a dû être glissée dans l''accord, à ton avis ?
[Femme] ...

A. Une garantie écrite que le projet sera réévalué à mi-parcours par un comité indépendant.
B. Une concession purement symbolique sur la dénomination du futur quartier.
C. Une compensation financière immédiate versée à chaque conseiller d''opposition.
D. Un arbitrage discret sur un dossier d''urbanisme cher à l''opposition, voté en échange.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">La majorité municipale a fini par voter le projet d''écoquartier.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">L''opposition s''y était farouchement opposée pendant six mois.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Et pourtant, le vote est passé presque sans débat.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Eu égard à cette volte-face, quelle contrepartie inavouée a dû être glissée dans l''accord, à ton avis ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Une garantie écrite que le projet sera réévalué à mi-parcours par un comité indépendant.<break time="700ms"/>B.<break time="300ms"/>Une concession purement symbolique sur la dénomination du futur quartier.<break time="700ms"/>C.<break time="300ms"/>Une compensation financière immédiate versée à chaque conseiller d''opposition.<break time="700ms"/>D.<break time="300ms"/>Un arbitrage discret sur un dossier d''urbanisme cher à l''opposition, voté en échange.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Le dialogue installe une volte-face inexplicable (opposition farouche → vote sans débat) et la question vise **la contrepartie cachée**, ni avouable publiquement, ni triviale. Seule D propose un **échange politique discret entre dossiers**, mécanisme classique d''accord tacite. A est **une garantie publique** (qui aurait pu être dite ouvertement, donc pas inavouée). B est **une concession trop superficielle** pour justifier la volte-face. C est **une accusation de corruption** — trop frontale et invraisemblable pour une « contrepartie inavouée » (qui se dissimule, mais reste légale).','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": true, "display_order": 4}]','fr-FR-HenriNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.437065+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c1-1000-0000-00000000000d','B2','co_dialogue_c1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] Tu lances ta marque de cosmétiques solides sans levée de fonds ?
[Femme] Exactement. Croissance lente, autofinancée, distribution sélective.
[Homme] Tu refuses donc explicitement la course au volume.
[Femme] Et derrière ce choix, il y a un pari de fond. Sur quoi paries-tu en réalité, selon toi ?
[Homme] ...

A. Sur le fait que la sobriété deviendra un argument commercial supérieur à la nouveauté permanente.
B. Sur la capacité de tes premiers clients à supporter des prix très élevés à long terme.
C. Sur un rachat éventuel par un grand groupe au bout de cinq ou six années.
D. Sur l''indifférence durable des concurrents installés vis-à-vis de ton segment.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tu lances ta marque de cosmétiques solides sans levée de fonds ?</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Exactement. Croissance lente, autofinancée, distribution sélective.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tu refuses donc explicitement la course au volume.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Et derrière ce choix, il y a un pari de fond. Sur quoi paries-tu en réalité, selon toi ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Sur le fait que la sobriété deviendra un argument commercial supérieur à la nouveauté permanente.<break time="700ms"/>B.<break time="300ms"/>Sur la capacité de tes premiers clients à supporter des prix très élevés à long terme.<break time="700ms"/>C.<break time="300ms"/>Sur un rachat éventuel par un grand groupe au bout de cinq ou six années.<break time="700ms"/>D.<break time="300ms"/>Sur l''indifférence durable des concurrents installés vis-à-vis de ton segment.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Le dialogue accumule trois traits stratégiques cohérents : pas de levée, croissance lente, refus du volume. La question demande **le pari profond qui sous-tend ce dispositif**, c''est-à-dire l''anticipation d''évolution du marché. Seule A formule ce pari structurant (la sobriété comme valeur commerciale dominante à venir). B identifie un **pari secondaire sur la clientèle** (« comptes-tu sur eux ? ») — plausible mais ne fonde pas la stratégie. C nomme **une porte de sortie financière** opposée au modèle décrit. D est **un pari négatif fragile** (« tu comptes que personne ne s''y intéressera ») qui contredit l''idée d''un marché émergent.','[{"label": "A", "is_correct": true, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-DeniseNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.437065+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c1-1000-0000-00000000000e','B2','co_dialogue_c1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Le ministre défend sa réforme en répétant qu''« il faut moderniser nos institutions ».
[Homme] Et personne ne discute le fond de cette affirmation.
[Femme] C''est précisément ce qui me frappe : le débat porte sur les modalités, jamais sur le principe.
[Homme] Tu pointes là un présupposé non discuté qui sous-tend toute sa position. Lequel, exactement ?
[Femme] ...

A. Que la modernisation entraîne nécessairement une amélioration tangible du service rendu.
B. Que nos institutions, telles qu''elles fonctionnent, seraient par nature dépassées et à reconfigurer.
C. Que la réforme ne peut être conduite sans l''adhésion préalable des partenaires sociaux.
D. Que les modalités techniques choisies seront politiquement neutres et consensuelles.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Le ministre défend sa réforme en répétant qu''« il faut moderniser nos institutions ».</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Et personne ne discute le fond de cette affirmation.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">C''est précisément ce qui me frappe : le débat porte sur les modalités, jamais sur le principe.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tu pointes là un présupposé non discuté qui sous-tend toute sa position. Lequel, exactement ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Que la modernisation entraîne nécessairement une amélioration tangible du service rendu.<break time="700ms"/>B.<break time="300ms"/>Que nos institutions, telles qu''elles fonctionnent, seraient par nature dépassées et à reconfigurer.<break time="700ms"/>C.<break time="300ms"/>Que la réforme ne peut être conduite sans l''adhésion préalable des partenaires sociaux.<break time="700ms"/>D.<break time="300ms"/>Que les modalités techniques choisies seront politiquement neutres et consensuelles.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','La femme distingue explicitement **principe** et **modalités** : le principe (« il faut moderniser ») n''est jamais interrogé. La question demande **le présupposé contenu dans cette affirmation-principe**. Seule B reformule ce présupposé latent : qu''il y aurait quelque chose à moderniser, donc que les institutions sont dépassées. A énonce **un autre présupposé**, lui aussi tacite mais portant sur la conséquence (« moderniser = mieux ») — distracteur très proche car effectivement présupposé, mais le tour 3 précise que c''est **le principe** qui n''est pas discuté, pas l''effet. C porte **sur la méthode** (modalités), donc ce qui est, lui, discuté. D porte **sur la neutralité des outils**, hors du sujet.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": true, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-HenriNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.437065+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c1-1000-0000-00000000000f','B2','co_dialogue_c1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] La discussion bloque toujours, paraît-il, sur les indicateurs de performance.
[Femme] C''est en tout cas ce que les deux parties répètent en réunion.
[Homme] Mais tu m''as glissé hier que la vraie pierre d''achoppement se trouvait ailleurs.
[Femme] Exactement. Le sujet des indicateurs n''est qu''un prétexte. La véritable pierre d''achoppement, c''est quoi en réalité ?
[Homme] ...

A. La méfiance personnelle entre les deux chefs de service, jamais nommée publiquement.
B. Une divergence ancienne sur la méthode statistique de calcul des indicateurs eux-mêmes.
C. Le refus tacite, côté direction, de céder un pouvoir d''arbitrage symbolique à l''autre service.
D. Un défaut chronique d''outils de mesure partagés entre les deux services.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">La discussion bloque toujours, paraît-il, sur les indicateurs de performance.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">C''est en tout cas ce que les deux parties répètent en réunion.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Mais tu m''as glissé hier que la vraie pierre d''achoppement se trouvait ailleurs.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Exactement. Le sujet des indicateurs n''est qu''un prétexte. La véritable pierre d''achoppement, c''est quoi en réalité ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>La méfiance personnelle entre les deux chefs de service, jamais nommée publiquement.<break time="700ms"/>B.<break time="300ms"/>Une divergence ancienne sur la méthode statistique de calcul des indicateurs eux-mêmes.<break time="700ms"/>C.<break time="300ms"/>Le refus tacite, côté direction, de céder un pouvoir d''arbitrage symbolique à l''autre service.<break time="700ms"/>D.<break time="300ms"/>Un défaut chronique d''outils de mesure partagés entre les deux services.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Le dialogue construit une opposition prétexte/véritable enjeu : les indicateurs ne sont qu''un masque. La question demande **le véritable point de blocage, distinct du prétexte affiché**. Seule C nomme un enjeu de pouvoir tacite (refus de céder un arbitrage), cohérent avec la logique du « prétexte ». A désigne une **lecture interpersonnelle** (« méfiance entre chefs ») — distracteur très proche, plausible, mais d''ordre relationnel, alors que le contexte (réunions, négociations) suggère un enjeu institutionnel. B reconduit **le sujet des indicateurs**, ce que la femme exclut expressément. D désigne **une difficulté technique**, encore une fois dans le registre du prétexte.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": true, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-DeniseNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.437065+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c1-1000-0000-000000000010','B2','co_dialogue_c1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Tu te disputes encore avec Antoine sur le choix de l''école pour Léa ?
[Homme] En apparence, oui : il défend le public, je préfère le privé sous contrat.
[Femme] Pourtant, vous étiez d''accord il y a six mois sur le principe d''une école proche.
[Homme] C''est bien là que le bât blesse. Le désaccord de fond entre nous est ailleurs, par contraste avec celui qui s''affiche.
[Femme] Selon toi, ce désaccord de fond porte sur quoi en réalité ?
[Homme] ...

A. Sur le quartier où nous voulons que Léa fasse sa scolarité.
B. Sur le budget que nous sommes prêts à consacrer à son éducation.
C. Sur la place du religieux dans le choix de l''établissement.
D. Sur le type d''enfant que chacun de nous voudrait qu''elle devienne, à travers cette école.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tu te disputes encore avec Antoine sur le choix de l''école pour Léa ?</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">En apparence, oui : il défend le public, je préfère le privé sous contrat.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Pourtant, vous étiez d''accord il y a six mois sur le principe d''une école proche.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">C''est bien là que le bât blesse. Le désaccord de fond entre nous est ailleurs, par contraste avec celui qui s''affiche.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Selon toi, ce désaccord de fond porte sur quoi en réalité ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Sur le quartier où nous voulons que Léa fasse sa scolarité.<break time="700ms"/>B.<break time="300ms"/>Sur le budget que nous sommes prêts à consacrer à son éducation.<break time="700ms"/>C.<break time="300ms"/>Sur la place du religieux dans le choix de l''établissement.<break time="700ms"/>D.<break time="300ms"/>Sur le type d''enfant que chacun de nous voudrait qu''elle devienne, à travers cette école.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Le dialogue oppose un désaccord de surface (public/privé) à un désaccord de fond distinct, plus profond que le simple choix d''école. La question demande **la nature véritable de cette divergence sous-jacente**. Seule D désigne un enjeu éducatif fondamental (projet d''enfant), qui peut expliquer pourquoi public ou privé devient un proxy. A reconduit **le critère géographique** déjà tranché (« d''accord sur l''école proche »). B introduit **une dimension matérielle** non évoquée. C propose **une lecture confessionnelle** (« privé sous contrat = religieux ») plausible, mais qui resterait du même ordre que le désaccord affiché.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": true, "display_order": 4}]','fr-FR-HenriNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.437065+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c1-1000-0000-000000000011','B2','co_dialogue_c1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] J''ai reçu un courriel surprenant de ma nouvelle directrice ce matin.
[Femme] Qu''est-ce qu''elle te dit, au juste ?
[Homme] Elle me félicite pour mon « investissement remarquable » et me suggère de penser, je cite, à « équilibrer davantage mes responsabilités avec d''autres dimensions de la vie ».
[Femme] La formule est belle, mais qu''est-ce qu''il fallait comprendre vraiment, entre les lignes ?
[Homme] ...

A. Qu''elle me trouve trop investi et redoute pour moi un essoufflement à court ou moyen terme.
B. Qu''elle me prépare officieusement à un changement de poste plus exposé.
C. Qu''elle attend de moi un investissement encore supérieur dans les mois à venir.
D. Qu''elle me reproche en creux mon manque d''engagement extra-professionnel.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">J''ai reçu un courriel surprenant de ma nouvelle directrice ce matin.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Qu''est-ce qu''elle te dit, au juste ?</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Elle me félicite pour mon « investissement remarquable » et me suggère de penser, je cite, à « équilibrer davantage mes responsabilités avec d''autres dimensions de la vie ».</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">La formule est belle, mais qu''est-ce qu''il fallait comprendre vraiment, entre les lignes ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Qu''elle me trouve trop investi et redoute pour moi un essoufflement à court ou moyen terme.<break time="700ms"/>B.<break time="300ms"/>Qu''elle me prépare officieusement à un changement de poste plus exposé.<break time="700ms"/>C.<break time="300ms"/>Qu''elle attend de moi un investissement encore supérieur dans les mois à venir.<break time="700ms"/>D.<break time="300ms"/>Qu''elle me reproche en creux mon manque d''engagement extra-professionnel.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Le message combine **éloge de l''investissement** et **suggestion d''équilibrer avec d''autres dimensions** : la lecture pragmatique attendue intègre les deux éléments. Seule A relie l''éloge (« tu en fais beaucoup ») à l''avertissement (« attention à toi »). B sur-interprète **vers une promotion** non suggérée. C contredit **frontalement** la suggestion d''équilibrer (« encore plus » contre « davantage d''équilibre »). D inverse **le reproche** (vie privée vs vie pro), à rebours du sens du message — distracteur fin C1 car formellement « équilibrer » peut concerner les deux côtés, mais le contexte (féliciter l''investissement professionnel) impose la direction.','[{"label": "A", "is_correct": true, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-DeniseNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.437065+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c1-1000-0000-000000000012','B2','co_dialogue_c1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] J''ai enfin vu la pièce de Mouawad que tu m''avais recommandée.
[Homme] Et qu''en as-tu pensé, finalement ?
[Femme] Bouleversante. On reste suspendu à la fratrie pendant deux heures, sans pouvoir détacher le regard.
[Homme] Mais quel est, à ton sens, le ressort dramatique principal qui fait tenir l''édifice ?
[Femme] ...

A. La beauté très formelle des dialogues, ciselés au mot près.
B. Le silence partagé sur un secret de famille que chacun pressent sans oser le formuler.
C. La mise en scène austère, qui laisse toute la place au texte.
D. La performance impressionnante de la comédienne principale, qui porte la pièce à elle seule.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">J''ai enfin vu la pièce de Mouawad que tu m''avais recommandée.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Et qu''en as-tu pensé, finalement ?</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Bouleversante. On reste suspendu à la fratrie pendant deux heures, sans pouvoir détacher le regard.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Mais quel est, à ton sens, le ressort dramatique principal qui fait tenir l''édifice ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>La beauté très formelle des dialogues, ciselés au mot près.<break time="700ms"/>B.<break time="300ms"/>Le silence partagé sur un secret de famille que chacun pressent sans oser le formuler.<break time="700ms"/>C.<break time="300ms"/>La mise en scène austère, qui laisse toute la place au texte.<break time="700ms"/>D.<break time="300ms"/>La performance impressionnante de la comédienne principale, qui porte la pièce à elle seule.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Le tour 3 souligne deux indices : l''attention captive et **la fratrie comme objet du regard**. La question demande **le ressort dramatique** — donc une tension narrative, pas un mérite formel. Seule B identifie un mécanisme dramaturgique (secret familial tu mais pressenti) qui justifie la suspension du regard sur la fratrie. A vante **une qualité d''écriture**, pas un ressort dramatique. C porte sur **la scénographie**, registre formel à nouveau — distracteur très proche car valorisable, mais ne tend pas l''action. D désigne **un mérite d''interprétation**.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": true, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-HenriNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.437065+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c1-1000-0000-000000000013','B2','co_dialogue_c1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] Tu as présenté ton rapport critique devant le conseil d''administration ?
[Femme] Oui, hier après-midi. Six administrateurs, trois heures de séance.
[Homme] J''imagine qu''ils ne t''ont pas ménagée.
[Femme] Ils m''ont attaquée sur tous les angles. Mais j''avais réfléchi à l''avance à la posture que je voulais tenir. Quelle posture as-tu choisie face à eux, à ton avis ?
[Homme] ...

A. Celle de la conciliation, en cherchant à reformuler chacune de leurs critiques pour les apaiser.
B. Celle du retrait poli, en différant systématiquement les réponses à une note écrite ultérieure.
C. Celle de la fermeté argumentée, en assumant chaque conclusion sans la durcir ni la nuancer.
D. Celle de la contre-attaque, en pointant à mon tour les angles morts de leur propre gouvernance.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tu as présenté ton rapport critique devant le conseil d''administration ?</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, hier après-midi. Six administrateurs, trois heures de séance.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">J''imagine qu''ils ne t''ont pas ménagée.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Ils m''ont attaquée sur tous les angles. Mais j''avais réfléchi à l''avance à la posture que je voulais tenir. Quelle posture as-tu choisie face à eux, à ton avis ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Celle de la conciliation, en cherchant à reformuler chacune de leurs critiques pour les apaiser.<break time="700ms"/>B.<break time="300ms"/>Celle du retrait poli, en différant systématiquement les réponses à une note écrite ultérieure.<break time="700ms"/>C.<break time="300ms"/>Celle de la fermeté argumentée, en assumant chaque conclusion sans la durcir ni la nuancer.<break time="700ms"/>D.<break time="300ms"/>Celle de la contre-attaque, en pointant à mon tour les angles morts de leur propre gouvernance.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Le contexte associe deux informations : rapport **critique** + posture **réfléchie à l''avance** (donc volontaire). La question demande **la posture délibérée tenue**, cohérente avec un rapport critique présenté à des opposants. Seule C combine assomption (fidélité au rapport) et tenue (ni durcissement ni nuance opportune) — posture caractéristique de l''auteur d''un rapport critique solide. A est **la conciliation**, contraire à l''idée d''un rapport critique tenu. B est **le retrait**, qui annulerait la fonction même de la séance. D est **la contre-attaque**, possible mais qui ferait dévier l''objet (de son rapport vers leur gouvernance) — distracteur très proche car aussi assumée.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": true, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-DeniseNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.437065+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c1-1000-0000-000000000014','B2','co_dialogue_c1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Lors du pot de départ, le directeur a fait un discours élogieux pour Vincent.
[Homme] Vincent qui, comme chacun le sait, part contraint, après deux années très difficiles.
[Femme] Personne, dans l''assemblée, n''a osé rappeler ce point.
[Homme] Tu m''as dit pourtant que tu avais hésité à prendre la parole.
[Femme] Oui. Et je m''interroge encore : qu''est-ce qu''il aurait fallu dire, à ce moment précis ?
[Homme] ...

A. Rien : ce genre de rituel social n''appelle aucune vérité dérangeante de la part des collègues.
B. Il aurait fallu prendre la parole pour critiquer publiquement la gestion du dossier par la direction.
C. Il aurait suffi d''applaudir un peu moins fort, pour marquer discrètement une distance.
D. Reconnaître brièvement et avec tact ce que ce départ avait de difficile, sans en faire un règlement de comptes.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Lors du pot de départ, le directeur a fait un discours élogieux pour Vincent.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Vincent qui, comme chacun le sait, part contraint, après deux années très difficiles.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Personne, dans l''assemblée, n''a osé rappeler ce point.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tu m''as dit pourtant que tu avais hésité à prendre la parole.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui. Et je m''interroge encore : qu''est-ce qu''il aurait fallu dire, à ce moment précis ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Rien : ce genre de rituel social n''appelle aucune vérité dérangeante de la part des collègues.<break time="700ms"/>B.<break time="300ms"/>Il aurait fallu prendre la parole pour critiquer publiquement la gestion du dossier par la direction.<break time="700ms"/>C.<break time="300ms"/>Il aurait suffi d''applaudir un peu moins fort, pour marquer discrètement une distance.<break time="700ms"/>D.<break time="300ms"/>Reconnaître brièvement et avec tact ce que ce départ avait de difficile, sans en faire un règlement de comptes.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Cinq tours installent une situation où une vérité partagée par tous n''est pas dite, et où la femme s''interroge sur **la parole juste**, ni la lâcheté du silence collectif ni la violence du règlement de comptes. La question, posée par elle-même après hésitation, attend **la formule médiane assumant la vérité avec tact**. Seule D propose cette voie d''équilibre. A justifie **le silence intégral**, position que la femme a précisément remise en cause. B propose **la dénonciation frontale** (« critiquer publiquement la direction »), qui transforme le rituel social en confrontation — distracteur très proche car aussi « dire la vérité ». C esquive **par un signal corporel** discret, qui ne « dit » rien et ne répond donc pas à la question (« qu''est-ce qu''il aurait fallu dire ? »).','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": true, "display_order": 4}]','fr-FR-HenriNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.437065+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c2-1000-0000-000000000001','B2','co_dialogue_c2_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Alors, ce dîner chez les Marchand, raconte-moi.
[Homme] Une soirée d''une rare élévation intellectuelle, ma chère.
[Femme] Tiens donc, à ce point ?
[Homme] Oui, j''ai cru défaillir devant tant d''esprit.
[Femme] Sois honnête : tu en as pensé quoi, vraiment ?
[Homme] ...

A. Que c''était d''une platitude consommée, en réalité.
B. Qu''ils ont, malgré tout, beaucoup de mérite à recevoir.
C. Que la conversation a culminé au moment du dessert.
D. Qu''ils m''ont gentiment raccompagné jusqu''à la porte.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Alors, ce dîner chez les Marchand, raconte-moi.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Une soirée d''une rare élévation intellectuelle, ma chère.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tiens donc, à ce point ?</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Oui, j''ai cru défaillir devant tant d''esprit.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Sois honnête : tu en as pensé quoi, vraiment ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Que c''était d''une platitude consommée, en réalité.<break time="700ms"/>B.<break time="300ms"/>Qu''ils ont, malgré tout, beaucoup de mérite à recevoir.<break time="700ms"/>C.<break time="300ms"/>Que la conversation a culminé au moment du dessert.<break time="700ms"/>D.<break time="300ms"/>Qu''ils m''ont gentiment raccompagné jusqu''à la porte.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Procédé : **antiphrase**. Henri loue avec emphase (« rare élévation », « défaillir devant tant d''esprit ») un dîner qu''il a en vérité trouvé ennuyeux ; la dernière question de Denise (« vraiment ? ») invite explicitement à dépasser l''ironie. Seule A « d''une platitude consommée » dit le jugement réel sous l''antiphrase. B propose une **lecture conciliante** (« malgré tout du mérite »), qui adoucit l''antiphrase au lieu de la décoder. C donne **un détail factuel** sur le déroulement du dîner. D donne **un détail mondain de courtoisie**. Une lecture littérale (le compliment) serait insuffisante car elle ignore la modulation ironique demandée par Denise.','[{"label": "A", "is_correct": true, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-DeniseNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.454459+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c2-1000-0000-000000000002','B2','co_dialogue_c2_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] Alors, cette nouvelle exposition au Grand Palais ?
[Femme] Disons que je n''en suis pas ressortie indifférente.
[Homme] Voilà une formule prudente. Cela t''a déplu, alors ?
[Femme] Loin s''en faut, vraiment.
[Homme] Sois plus claire : qu''as-tu réellement éprouvé ?
[Femme] ...

A. Que les salles étaient particulièrement bondées ce jour-là.
B. Que j''ai été déçue, comme à mon habitude désormais.
C. Que l''affiche promettait davantage qu''elle ne tenait.
D. Que j''ai été littéralement bouleversée par l''ensemble.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Alors, cette nouvelle exposition au Grand Palais ?</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Disons que je n''en suis pas ressortie indifférente.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Voilà une formule prudente. Cela t''a déplu, alors ?</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Loin s''en faut, vraiment.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Sois plus claire : qu''as-tu réellement éprouvé ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Que les salles étaient particulièrement bondées ce jour-là.<break time="700ms"/>B.<break time="300ms"/>Que j''ai été déçue, comme à mon habitude désormais.<break time="700ms"/>C.<break time="300ms"/>Que l''affiche promettait davantage qu''elle ne tenait.<break time="700ms"/>D.<break time="300ms"/>Que j''ai été littéralement bouleversée par l''ensemble.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Procédé : **litote**. « Je n''en suis pas ressortie indifférente » et « loin s''en faut » sont deux atténuations par négation qui signifient un sentiment fort et positif ; Henri presse pour passer du dit (la prudence) au pensé (l''émotion réelle). Seule D « littéralement bouleversée » dit ce sentiment plein. A donne **un détail circonstanciel** (la foule). B propose **la lecture inverse** (déception), incompatible avec « loin s''en faut » qui repousse précisément l''idée d''un déplaisir. C propose **une critique modérée**, ce qui revient à manquer la force positive de la litote. Lire littéralement « pas indifférente » comme « tiède » serait précisément le contresens à éviter.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": true, "display_order": 4}]','fr-FR-HenriNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.454459+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c2-1000-0000-000000000003','B2','co_dialogue_c2_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Le nouveau directeur a tenu son grand discours stratégique, hier.
[Homme] Ah, enfin un visionnaire à la barre.
[Femme] Tu m''as l''air dubitatif, malgré le compliment.
[Homme] Il a redécouvert l''eau tiède avec un aplomb remarquable.
[Femme] Alors concrètement, quel jugement tu portes sur lui ?
[Homme] ...

A. Qu''il bénéficie d''un soutien indéfectible du comité.
B. Qu''il enrobe des évidences avec une assurance déconcertante.
C. Qu''il prend ses fonctions dans un contexte tendu.
D. Qu''il a parlé près d''une heure devant l''ensemble du comité.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Le nouveau directeur a tenu son grand discours stratégique, hier.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Ah, enfin un visionnaire à la barre.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tu m''as l''air dubitatif, malgré le compliment.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Il a redécouvert l''eau tiède avec un aplomb remarquable.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Alors concrètement, quel jugement tu portes sur lui ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Qu''il bénéficie d''un soutien indéfectible du comité.<break time="700ms"/>B.<break time="300ms"/>Qu''il enrobe des évidences avec une assurance déconcertante.<break time="700ms"/>C.<break time="300ms"/>Qu''il prend ses fonctions dans un contexte tendu.<break time="700ms"/>D.<break time="300ms"/>Qu''il a parlé près d''une heure devant l''ensemble du comité.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Procédé : **ironie mordante** filée. « Visionnaire à la barre » est posé puis aussitôt sapé par « redécouvert l''eau tiède », expression idiomatique pour banaliser une découverte ; Denise demande explicitement le jugement réel. Seule B « il enrobe des évidences avec aplomb » paraphrase exactement la pique. A donne **un fait politique** (soutien hiérarchique), neutre. C donne **un cadre conjoncturel** sans porter de jugement. D donne **un fait factuel** (durée de l''intervention). Une lecture littérale du « visionnaire » ferait l''impasse sur la métaphore figée qui inverse l''éloge.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": true, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-HenriNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.454459+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c2-1000-0000-000000000004','B2','co_dialogue_c2_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Tu as enfin lu le manuscrit de Romain ?
[Homme] C''est un travail très appliqué, on le sent à chaque page.
[Femme] Très appliqué… mais encore ?
[Homme] Oh, il maîtrise vraiment toutes les règles qu''on lui a apprises.
[Femme] Bref, ton compliment cache quoi, au juste ?
[Homme] ...

A. Que je n''ai pas eu le temps de tout lire jusqu''au bout.
B. Qu''il a manifestement progressé depuis son premier roman.
C. Qu''il manque cruellement de souffle et d''invention propre.
D. Qu''il a travaillé près de deux ans sur ce manuscrit.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tu as enfin lu le manuscrit de Romain ?</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">C''est un travail très appliqué, on le sent à chaque page.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Très appliqué… mais encore ?</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Oh, il maîtrise vraiment toutes les règles qu''on lui a apprises.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Bref, ton compliment cache quoi, au juste ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Que je n''ai pas eu le temps de tout lire jusqu''au bout.<break time="700ms"/>B.<break time="300ms"/>Qu''il a manifestement progressé depuis son premier roman.<break time="700ms"/>C.<break time="300ms"/>Qu''il manque cruellement de souffle et d''invention propre.<break time="700ms"/>D.<break time="300ms"/>Qu''il a travaillé près de deux ans sur ce manuscrit.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Procédé : **compliment ambigu** (faux éloge). « Très appliqué » et « toutes les règles qu''on lui a apprises » sont des adjectifs scolaires qui signalent en creux l''absence d''originalité ; Denise demande explicitement ce que le compliment dissimule. Seule C « manque de souffle et d''invention propre » formule cette réserve cachée. A donne **une excuse personnelle** (lecture inachevée). B donne **une lecture bienveillante** (progrès), qui prend le compliment au pied de la lettre. D donne **un fait extérieur** (durée du travail). Une lecture littérale lirait C comme un éloge ; il faut entendre la sous-évaluation discrète.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": true, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-DeniseNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.454459+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c2-1000-0000-000000000005','B2','co_dialogue_c2_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Tu as encore réussi à filer avant la fin du repas de famille.
[Homme] J''avais un dossier qui ne pouvait pas attendre, hélas.
[Femme] Bien sûr. Quelle constance, vraiment, dans tes obligations.
[Homme] Tu le dis sur un ton qui n''augure rien de bon.
[Femme] Sois lucide : où se niche le reproche, en fait ?
[Homme] ...

A. Dans le fait que je m''éclipse systématiquement à chaque occasion.
B. Dans la régularité dont tu reconnais, malgré tout, le mérite.
C. Dans le ton sec sur lequel tu m''as accueilli hier soir.
D. Dans l''heure tardive à laquelle j''avais fini de travailler.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tu as encore réussi à filer avant la fin du repas de famille.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">J''avais un dossier qui ne pouvait pas attendre, hélas.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Bien sûr. Quelle constance, vraiment, dans tes obligations.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tu le dis sur un ton qui n''augure rien de bon.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Sois lucide : où se niche le reproche, en fait ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Dans le fait que je m''éclipse systématiquement à chaque occasion.<break time="700ms"/>B.<break time="300ms"/>Dans la régularité dont tu reconnais, malgré tout, le mérite.<break time="700ms"/>C.<break time="300ms"/>Dans le ton sec sur lequel tu m''as accueilli hier soir.<break time="700ms"/>D.<break time="300ms"/>Dans l''heure tardive à laquelle j''avais fini de travailler.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Procédé : **reproche déguisé en compliment**. « Quelle constance, vraiment » loue en apparence une qualité (la régularité) mais vise en réalité la répétition d''une dérobade (« encore réussi à filer »). Henri doit reconnaître que le reproche porte sur la systématicité de ses fuites. Seule A « je m''éclipse systématiquement » identifie cela. B propose une **lecture naïve** qui prend le compliment au sérieux. C déplace **le grief sur le ton de l''autre**, hors propos. D **invoque une justification** (l''heure du travail), ce qui esquive la cible.','[{"label": "A", "is_correct": true, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-DeniseNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.454459+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c2-1000-0000-000000000006','B2','co_dialogue_c2_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] La direction a annoncé un nouveau plan de transformation.
[Femme] Magnifique, le troisième en dix-huit mois, quel élan.
[Homme] Tu as l''air positivement enthousiaste, dis-moi.
[Femme] Comment ne pas l''être, devant tant de cohérence stratégique ?
[Homme] Sérieusement, qu''est-ce que tu ressens, au fond ?
[Femme] ...

A. Une vraie reconnaissance pour le courage de la direction.
B. Un découragement profond face à cette agitation perpétuelle.
C. Une attente prudente avant de me prononcer définitivement.
D. Un certain agacement contre la presse qui en parle.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">La direction a annoncé un nouveau plan de transformation.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Magnifique, le troisième en dix-huit mois, quel élan.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tu as l''air positivement enthousiaste, dis-moi.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Comment ne pas l''être, devant tant de cohérence stratégique ?</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Sérieusement, qu''est-ce que tu ressens, au fond ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Une vraie reconnaissance pour le courage de la direction.<break time="700ms"/>B.<break time="300ms"/>Un découragement profond face à cette agitation perpétuelle.<break time="700ms"/>C.<break time="300ms"/>Une attente prudente avant de me prononcer définitivement.<break time="700ms"/>D.<break time="300ms"/>Un certain agacement contre la presse qui en parle.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Procédé : **sarcasme**. L''accumulation « magnifique », « troisième en dix-huit mois », « tant de cohérence stratégique » avec le mot « stratégique » miné par la fréquence des plans, signale une amertume à peine voilée ; la question d''Henri demande le sentiment réel. Seule B « un découragement profond face à cette agitation perpétuelle » nomme ce sentiment. A propose **la lecture naïve** (vraie reconnaissance). C **adoucit en attentisme**, ce qui ne dit pas le sentiment réel. D **déplace la cible** vers la presse, ce qui n''est pas l''objet du sarcasme.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": true, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-HenriNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.454459+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c2-1000-0000-000000000007','B2','co_dialogue_c2_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Tu disais que la posture de ce ministre te paraissait familière.
[Homme] Oui, j''avais en tête une figure très précise, en l''écoutant.
[Femme] Vraiment ?
[Homme] Tartuffe, finalement, n''aurait pas mieux composé son visage.
[Femme] À quoi tu fais allusion, au juste ?
[Homme] ...

A. À la longueur excessive de son intervention télévisée.
B. À ses positions, qui ont varié au cours du dernier mois.
C. À une hypocrisie soigneusement mise en scène par ses soins.
D. À sa fébrilité visible lors de la séance de questions.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tu disais que la posture de ce ministre te paraissait familière.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Oui, j''avais en tête une figure très précise, en l''écoutant.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Vraiment ?</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tartuffe, finalement, n''aurait pas mieux composé son visage.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">À quoi tu fais allusion, au juste ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>À la longueur excessive de son intervention télévisée.<break time="700ms"/>B.<break time="300ms"/>À ses positions, qui ont varié au cours du dernier mois.<break time="700ms"/>C.<break time="300ms"/>À une hypocrisie soigneusement mise en scène par ses soins.<break time="700ms"/>D.<break time="300ms"/>À sa fébrilité visible lors de la séance de questions.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Procédé : **allusion littéraire**. Tartuffe, archétype molièresque du faux dévot, désigne l''hypocrisie ostensible et étudiée ; « composer son visage » renforce l''image de la mascarade. Seule C « hypocrisie soigneusement mise en scène » décode la référence. A donne **un défaut de forme** (durée). B donne **un autre grief** (revirements), proche thématiquement mais distinct du procédé tartufien. D donne **un trait psychologique opposé** (fébrilité, alors que Tartuffe est maître de son visage). Lire « Tartuffe » seulement comme « personnage connu » sans en mobiliser le sens propre serait insuffisant.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": true, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-DeniseNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.454459+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c2-1000-0000-000000000008','B2','co_dialogue_c2_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Tu as vu, on a placé Charlotte au bout de la table, près des enfants.
[Homme] Tiens donc. Cela n''avait rien d''anodin, je présume.
[Femme] Bien sûr que non. C''est un message en soi.
[Homme] Et qu''est-ce qu''on a voulu lui signifier, au juste ?
[Femme] ...

A. Qu''elle s''entend particulièrement bien avec les plus jeunes.
B. Qu''on souhaitait, par cette place, alléger le service à table.
C. Qu''elle aurait préféré, à l''évidence, dîner ailleurs ce soir-là.
D. Qu''elle n''est plus considérée comme tout à fait des nôtres.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tu as vu, on a placé Charlotte au bout de la table, près des enfants.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tiens donc. Cela n''avait rien d''anodin, je présume.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Bien sûr que non. C''est un message en soi.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Et qu''est-ce qu''on a voulu lui signifier, au juste ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Qu''elle s''entend particulièrement bien avec les plus jeunes.<break time="700ms"/>B.<break time="300ms"/>Qu''on souhaitait, par cette place, alléger le service à table.<break time="700ms"/>C.<break time="300ms"/>Qu''elle aurait préféré, à l''évidence, dîner ailleurs ce soir-là.<break time="700ms"/>D.<break time="300ms"/>Qu''elle n''est plus considérée comme tout à fait des nôtres.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Procédé : **sous-entendu mondain (placement à table)**. Le « bout de la table, près des enfants » est, dans le code mondain, une marque symbolique de relégation ; Denise valide explicitement (« message en soi »). Seule D « plus considérée comme tout à fait des nôtres » dit la mise à distance signifiée. A propose **une lecture bienveillante** (affinité avec les enfants). B propose **une justification logistique**, qui nie le caractère intentionnel. C **déplace la question** sur le ressenti de Charlotte plutôt que sur le message envoyé.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": true, "display_order": 4}]','fr-FR-HenriNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.454459+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c2-1000-0000-000000000009','B2','co_dialogue_c2_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] Comment tu as trouvé l''intervention de notre confrère Dupuis ?
[Femme] C''est, à n''en pas douter, un esprit méritant.
[Homme] Méritant ? Le qualificatif est délicieusement choisi.
[Femme] Disons que je salue son sérieux, à défaut d''autre chose.
[Homme] Quel mépris perce sous tant de courtoisie ?
[Femme] ...

A. Que je le tiens, en somme, pour un esprit bien laborieux.
B. Que je l''estime, finalement, plus que je ne le laisse paraître.
C. Que je lui reconnais des qualités humaines indéniables.
D. Que je le trouve très investi, mais un peu inexpérimenté.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Comment tu as trouvé l''intervention de notre confrère Dupuis ?</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">C''est, à n''en pas douter, un esprit méritant.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Méritant ? Le qualificatif est délicieusement choisi.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Disons que je salue son sérieux, à défaut d''autre chose.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Quel mépris perce sous tant de courtoisie ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Que je le tiens, en somme, pour un esprit bien laborieux.<break time="700ms"/>B.<break time="300ms"/>Que je l''estime, finalement, plus que je ne le laisse paraître.<break time="700ms"/>C.<break time="300ms"/>Que je lui reconnais des qualités humaines indéniables.<break time="700ms"/>D.<break time="300ms"/>Que je le trouve très investi, mais un peu inexpérimenté.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Procédé : **mépris voilé sous la politesse**. « Méritant », « sérieux à défaut d''autre chose » signalent une condescendance qui salue la peine mais nie le talent ; Henri demande explicitement ce que la politesse dissimule. Seule A « un esprit bien laborieux » nomme ce mépris à peine voilé. B propose **la lecture inverse** (estime cachée). C **prend la politesse pour argent comptant**. D **adoucit en concession bienveillante** (« investi mais inexpérimenté »), ce qui n''est pas du mépris.','[{"label": "A", "is_correct": true, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-HenriNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.454459+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c2-1000-0000-00000000000a','B2','co_dialogue_c2_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Tu as encore reporté ton projet de roman, à ce que je vois.
[Homme] Oui, je peaufine ma procrastination jusqu''à un art véritable.
[Femme] Élégante manière de te flageller, dis-moi.
[Homme] Je me console comme je peux de ma propre paresse.
[Femme] Au fond, comment te moques-tu de toi-même, là ?
[Homme] ...

A. Je trouve, malgré tout, mon courage assez remarquable.
B. Je transforme un défaut bien réel en posture d''esthète.
C. Je dénonce avant tout la pression sociale qui pèse sur moi.
D. Je rends hommage à mes éditeurs, qui demeurent patients.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tu as encore reporté ton projet de roman, à ce que je vois.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Oui, je peaufine ma procrastination jusqu''à un art véritable.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Élégante manière de te flageller, dis-moi.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Je me console comme je peux de ma propre paresse.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Au fond, comment te moques-tu de toi-même, là ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Je trouve, malgré tout, mon courage assez remarquable.<break time="700ms"/>B.<break time="300ms"/>Je transforme un défaut bien réel en posture d''esthète.<break time="700ms"/>C.<break time="300ms"/>Je dénonce avant tout la pression sociale qui pèse sur moi.<break time="700ms"/>D.<break time="300ms"/>Je rends hommage à mes éditeurs, qui demeurent patients.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Procédé : **auto-ironie**. « Je peaufine ma procrastination jusqu''à un art véritable » est une **hyperbole** qui esthétise un défaut (la paresse, reconnue au tour suivant). Seule B « je transforme un défaut bien réel en posture d''esthète » nomme exactement ce procédé d''auto-dénigrement valorisant. A propose **un éloge littéral** de soi, contradiction directe. C **déplace la critique sur autrui** (pression sociale). D introduit **un tiers** (les éditeurs) hors champ.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": true, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-DeniseNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.454459+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c2-1000-0000-00000000000b','B2','co_dialogue_c2_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Tu vas reconnaître que la réforme avance, tout de même.
[Homme] Oh, je veux bien lui accorder le mérite d''exister, à défaut d''agir.
[Femme] Voilà une concession à double tranchant, je trouve.
[Homme] Disons que je consens à l''évidence, et rien de plus.
[Femme] Qu''est-ce que tu concèdes vraiment, alors ?
[Homme] ...

A. Que cette réforme produira, à terme, des effets bénéfiques.
B. Que ses promoteurs ont déployé une énergie remarquable.
C. Strictement rien, sinon le fait qu''un texte ait été publié.
D. Que le calendrier de mise en œuvre est globalement tenu.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tu vas reconnaître que la réforme avance, tout de même.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Oh, je veux bien lui accorder le mérite d''exister, à défaut d''agir.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Voilà une concession à double tranchant, je trouve.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Disons que je consens à l''évidence, et rien de plus.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Qu''est-ce que tu concèdes vraiment, alors ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Que cette réforme produira, à terme, des effets bénéfiques.<break time="700ms"/>B.<break time="300ms"/>Que ses promoteurs ont déployé une énergie remarquable.<break time="700ms"/>C.<break time="300ms"/>Strictement rien, sinon le fait qu''un texte ait été publié.<break time="700ms"/>D.<break time="300ms"/>Que le calendrier de mise en œuvre est globalement tenu.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Procédé : **concession ironique**. « Le mérite d''exister, à défaut d''agir » et « consens à l''évidence, et rien de plus » sont des concessions minimales qui vident la concession de toute substance ; Denise demande la teneur réelle. Seule C « strictement rien, sinon le fait qu''un texte ait été publié » dit la concession vide. A, B, D proposent **des concessions substantielles** (efficacité, énergie, calendrier), qui prennent la concession au pied de la lettre, alors qu''Henri refuse précisément d''accorder plus que l''existence du texte.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": true, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-DeniseNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.454459+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c2-1000-0000-00000000000c','B2','co_dialogue_c2_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Comment s''est terminée ta réunion avec le comité d''éthique ?
[Homme] On a essayé de leur ressortir le même baratin, et puis bon, ça a foiré.
[Femme] Tu changes brutalement de registre, c''est frappant.
[Homme] Disons que la situation appelait quelques mots crus.
[Femme] Qu''est-ce qui détonne dans ton ton, à ton avis ?
[Homme] ...

A. Un vocabulaire technique inhabituellement précis pour le sujet.
B. Une politesse glaciale qui trahit ma profonde colère intérieure.
C. Un ton martial inattendu, vu mon caractère ordinaire.
D. Un argot soudain dans un cadre que d''ordinaire je tiens feutré.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Comment s''est terminée ta réunion avec le comité d''éthique ?</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">On a essayé de leur ressortir le même baratin, et puis bon, ça a foiré.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tu changes brutalement de registre, c''est frappant.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Disons que la situation appelait quelques mots crus.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Qu''est-ce qui détonne dans ton ton, à ton avis ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Un vocabulaire technique inhabituellement précis pour le sujet.<break time="700ms"/>B.<break time="300ms"/>Une politesse glaciale qui trahit ma profonde colère intérieure.<break time="700ms"/>C.<break time="300ms"/>Un ton martial inattendu, vu mon caractère ordinaire.<break time="700ms"/>D.<break time="300ms"/>Un argot soudain dans un cadre que d''ordinaire je tiens feutré.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Procédé : **décalage de registre**. « Baratin » et « ça a foiré » sont des termes familiers, presque argotiques, surgis dans un contexte feutré (comité d''éthique) ; Denise pointe explicitement le décalage. Seule D « un argot soudain dans un cadre feutré » nomme exactement ce décalage. A désigne **un autre registre opposé** (technique précis), pas du tout celui employé. B nomme **un registre opposé** (politesse glaciale). C nomme **un registre martial**, étranger au lexique entendu. La lecture première — juger le contenu seul — manquerait l''écart de niveau de langue qui fait le sel du tour.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": true, "display_order": 4}]','fr-FR-DeniseNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.454459+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c2-1000-0000-00000000000d','B2','co_dialogue_c2_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] Tu n''as pas été tendre avec le dernier film d''Anaïs Mercier.
[Femme] Je lui reproche surtout d''être devenue insupportablement exigeante.
[Homme] Voilà un reproche qui ressemble fort à un compliment.
[Femme] Disons que personne ne se donne autant de mal pour me décevoir.
[Homme] Quel hommage perce, en réalité, sous ta critique ?
[Femme] ...

A. Qu''elle place la barre si haut que toute baisse paraît un drame.
B. Que ses films, désormais, ne valent plus la peine d''être vus.
C. Qu''elle s''est égarée dans des sujets trop personnels pour elle.
D. Que la critique a, dans l''ensemble, été bien trop indulgente.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tu n''as pas été tendre avec le dernier film d''Anaïs Mercier.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Je lui reproche surtout d''être devenue insupportablement exigeante.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Voilà un reproche qui ressemble fort à un compliment.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Disons que personne ne se donne autant de mal pour me décevoir.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Quel hommage perce, en réalité, sous ta critique ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Qu''elle place la barre si haut que toute baisse paraît un drame.<break time="700ms"/>B.<break time="300ms"/>Que ses films, désormais, ne valent plus la peine d''être vus.<break time="700ms"/>C.<break time="300ms"/>Qu''elle s''est égarée dans des sujets trop personnels pour elle.<break time="700ms"/>D.<break time="300ms"/>Que la critique a, dans l''ensemble, été bien trop indulgente.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Procédé : **hommage déguisé en critique**. « Insupportablement exigeante » et « personne ne se donne autant de mal pour me décevoir » sont des reproches dont la forme suppose une attente d''excellence ; Henri explicite l''hommage caché. Seule A « elle place la barre si haut que toute baisse paraît un drame » formule l''éloge contenu dans le reproche. B propose **une critique pleine** (sans hommage). C donne **un autre grief artistique**. D **déplace la critique** sur les autres critiques.','[{"label": "A", "is_correct": true, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-HenriNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.454459+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c2-1000-0000-00000000000e','B2','co_dialogue_c2_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Tu as croisé Béatrice, hier ? Comment l''as-tu trouvée ?
[Homme] Elle est, pour son âge, étonnamment bien conservée.
[Femme] Tiens, voilà un compliment qui pique un peu.
[Homme] J''ai voulu être aimable, je crois avoir réussi.
[Femme] Sois honnête : qu''est-ce qui est venimeux, là-dedans ?
[Homme] ...

A. Le fait d''avoir préféré la croiser plutôt que de l''appeler.
B. La précision « pour son âge », qui aigrit tout l''éloge.
C. Le verbe « trouver », un peu trop évaluateur pour la circonstance.
D. Le tour passif « bien conservée », vaguement médical et neutre.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tu as croisé Béatrice, hier ? Comment l''as-tu trouvée ?</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Elle est, pour son âge, étonnamment bien conservée.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tiens, voilà un compliment qui pique un peu.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">J''ai voulu être aimable, je crois avoir réussi.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Sois honnête : qu''est-ce qui est venimeux, là-dedans ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Le fait d''avoir préféré la croiser plutôt que de l''appeler.<break time="700ms"/>B.<break time="300ms"/>La précision « pour son âge », qui aigrit tout l''éloge.<break time="700ms"/>C.<break time="300ms"/>Le verbe « trouver », un peu trop évaluateur pour la circonstance.<break time="700ms"/>D.<break time="300ms"/>Le tour passif « bien conservée », vaguement médical et neutre.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Procédé : **compliment empoisonné**. La restriction « pour son âge » introduit une comparaison défavorable implicite qui retire la portée à « étonnamment bien conservée » ; Denise pointe ce qui « pique ». Seule B nomme la clause restrictive comme foyer du venin. A déplace **sur un autre grief** (préférer croiser plutôt qu''appeler). C **incrimine un autre mot** (« trouver »), qui n''est pas le poison. D **désamorce** en présentant « bien conservée » comme « neutre », ce qui passe à côté du venin réel logé dans la restriction.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": true, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-DeniseNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.454459+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c2-1000-0000-00000000000f','B2','co_dialogue_c2_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] Tu crois vraiment que ce gouvernement va tenir jusqu''aux élections ?
[Femme] A-t-on jamais vu une majorité aussi friable durer six mois ?
[Homme] Ce n''est pas tout à fait une réponse, ça.
[Femme] Le passé récent fournit, je crois, tous les éléments de réponse.
[Homme] Quelle est, en clair, la vraie affirmation derrière ta question ?
[Femme] ...

A. Que tu sous-estimes la résilience des coalitions improvisées.
B. Que beaucoup d''observateurs se trompent depuis quelques mois.
C. Qu''aucune coalition aussi fragile n''a jamais tenu jusqu''au terme.
D. Que ce gouvernement traverse une zone de turbulences passagère.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tu crois vraiment que ce gouvernement va tenir jusqu''aux élections ?</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">A-t-on jamais vu une majorité aussi friable durer six mois ?</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Ce n''est pas tout à fait une réponse, ça.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Le passé récent fournit, je crois, tous les éléments de réponse.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Quelle est, en clair, la vraie affirmation derrière ta question ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Que tu sous-estimes la résilience des coalitions improvisées.<break time="700ms"/>B.<break time="300ms"/>Que beaucoup d''observateurs se trompent depuis quelques mois.<break time="700ms"/>C.<break time="300ms"/>Qu''aucune coalition aussi fragile n''a jamais tenu jusqu''au terme.<break time="700ms"/>D.<break time="300ms"/>Que ce gouvernement traverse une zone de turbulences passagère.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Procédé : **question rhétorique**. « A-t-on jamais vu une majorité aussi friable durer six mois ? » attend la réponse « non » ; c''est donc une affirmation négative déguisée. Seule C « aucune coalition aussi fragile n''a jamais tenu jusqu''au terme » formule cette affirmation. A **renverse la perspective** (sur Henri). B **déplace la critique** sur d''autres observateurs. D propose **la lecture inverse** (gouvernement durable), qui contredit la question rhétorique.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": true, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-HenriNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.454459+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c2-1000-0000-000000000010','B2','co_dialogue_c2_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] On m''a annoncé ce matin un « repositionnement stratégique » de mon poste.
[Homme] Ouh là. Ce sont des mots à manipuler avec précaution.
[Femme] Le directeur a évoqué un « ajustement de périmètre temporaire ».
[Homme] Voilà des formulations toutes prêtes à amortir un choc.
[Femme] À ton avis, qu''est-ce que tout ce vocabulaire adoucit, vraiment ?
[Homme] ...

A. Une promotion latérale, somme toute assez flatteuse pour toi.
B. Un simple changement de bureau, plus proche de la direction.
C. Une réorganisation neutre, dictée par l''évolution des marchés.
D. Un placard discret, où l''on te laisse sans réelle mission claire.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">On m''a annoncé ce matin un « repositionnement stratégique » de mon poste.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Ouh là. Ce sont des mots à manipuler avec précaution.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Le directeur a évoqué un « ajustement de périmètre temporaire ».</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Voilà des formulations toutes prêtes à amortir un choc.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">À ton avis, qu''est-ce que tout ce vocabulaire adoucit, vraiment ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Une promotion latérale, somme toute assez flatteuse pour toi.<break time="700ms"/>B.<break time="300ms"/>Un simple changement de bureau, plus proche de la direction.<break time="700ms"/>C.<break time="300ms"/>Une réorganisation neutre, dictée par l''évolution des marchés.<break time="700ms"/>D.<break time="300ms"/>Un placard discret, où l''on te laisse sans réelle mission claire.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Procédé : **euphémisme à percer**. « Repositionnement stratégique » et « ajustement de périmètre temporaire » sont des formules feutrées du jargon RH qui adoucissent une mise à l''écart ; Henri en signale le caractère amortisseur. Seule D « un placard discret » nomme la réalité brute. A, B, C proposent **trois lectures littérales / bienveillantes** (promotion, changement anodin, contexte de marché) qui prennent l''euphémisme pour vérité au lieu de le percer.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": true, "display_order": 4}]','fr-FR-HenriNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.454459+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c2-1000-0000-000000000011','B2','co_dialogue_c2_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] Tu es retournée dans ton village d''enfance, finalement.
[Femme] Oui, après tant d''années.
[Homme] Tu m''en parles d''une voix curieuse, presque retenue.
[Femme] Les pierres sont restées, mais ceux qui les habitaient s''en sont allés.
[Homme] Quelle tonalité, exactement, traverse ce que tu me racontes ?
[Femme] ...

A. Une douceur mélancolique pour un monde irrémédiablement disparu.
B. Une exaspération nette devant l''abandon du patrimoine local.
C. Une joie franche d''avoir retrouvé un cadre intact, finalement.
D. Une indifférence cultivée envers un lieu qui ne me dit plus rien.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tu es retournée dans ton village d''enfance, finalement.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, après tant d''années.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tu m''en parles d''une voix curieuse, presque retenue.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Les pierres sont restées, mais ceux qui les habitaient s''en sont allés.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Quelle tonalité, exactement, traverse ce que tu me racontes ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Une douceur mélancolique pour un monde irrémédiablement disparu.<break time="700ms"/>B.<break time="300ms"/>Une exaspération nette devant l''abandon du patrimoine local.<break time="700ms"/>C.<break time="300ms"/>Une joie franche d''avoir retrouvé un cadre intact, finalement.<break time="700ms"/>D.<break time="300ms"/>Une indifférence cultivée envers un lieu qui ne me dit plus rien.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Procédé : **tonalité élégiaque**. La phrase « les pierres sont restées, mais ceux qui les habitaient s''en sont allés » oppose la permanence du décor à la disparition des êtres : c''est la structure typique de l''élégie, doux regret de ce qui n''est plus. Seule A « douceur mélancolique pour un monde disparu » nomme cette tonalité. B propose **la colère** (registre étranger à l''élégie). C propose **la joie**, contredite par « s''en sont allés ». D propose **l''indifférence**, contredite par la voix « retenue » et l''attention au détail.','[{"label": "A", "is_correct": true, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-DeniseNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.454459+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c2-1000-0000-000000000012','B2','co_dialogue_c2_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Tu sais que ma fille fréquente désormais ce jeune Hugo, dont nous parlions.
[Homme] Ah, le fils Berger. Un garçon, m''a-t-on dit, plein d''avenir.
[Femme] Plein d''avenir, certes, mais issu d''un milieu si différent du nôtre.
[Homme] Quel implicite sur leur écart de monde tu glisses, là ?
[Femme] ...

A. Qu''il finira par s''adapter sans trop de difficultés à nos usages.
B. Qu''il n''est pas vraiment des nôtres, et que cela finira par peser.
C. Qu''il est, malgré tout, un parti tout à fait recommandable pour elle.
D. Qu''il vient d''une famille modeste, mais courageuse et estimable.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tu sais que ma fille fréquente désormais ce jeune Hugo, dont nous parlions.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Ah, le fils Berger. Un garçon, m''a-t-on dit, plein d''avenir.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Plein d''avenir, certes, mais issu d''un milieu si différent du nôtre.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Quel implicite sur leur écart de monde tu glisses, là ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Qu''il finira par s''adapter sans trop de difficultés à nos usages.<break time="700ms"/>B.<break time="300ms"/>Qu''il n''est pas vraiment des nôtres, et que cela finira par peser.<break time="700ms"/>C.<break time="300ms"/>Qu''il est, malgré tout, un parti tout à fait recommandable pour elle.<break time="700ms"/>D.<break time="300ms"/>Qu''il vient d''une famille modeste, mais courageuse et estimable.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Procédé : **implicite de classe**. « Issu d''un milieu si différent du nôtre » est une formulation feutrée typique du discours mondain, qui pose une frontière de classe ; le « certes / mais » marque l''opposition entre l''éloge concédé et la réserve réelle. Seule B « il n''est pas vraiment des nôtres, et cela finira par peser » dit le pronostic implicite. A propose **un optimisme intégrateur** que la mère ne formule pas. C propose **un éloge net**, contredit par la concessive. D **adoucit** en éloge moral, sans nommer la distance de classe.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": true, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-HenriNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.454459+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c2-1000-0000-000000000013','B2','co_dialogue_c2_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Le dernier livre d''entretiens a fait jaser, dans les ministères.
[Homme] Tu veux parler de celui où l''on évoque « l''ancien locataire de l''hôtel Matignon » ?
[Femme] C''est bien ce volume-là.
[Homme] Cette périphrase a, paraît-il, beaucoup amusé son destinataire.
[Femme] Qui désigne au juste, en clair, cette belle périphrase ?
[Homme] ...

A. Le président de la République actuellement en exercice.
B. Le ministre des Affaires étrangères du gouvernement précédent.
C. Un ancien Premier ministre français récemment quitté de ses fonctions.
D. Le porte-parole habituel du gouvernement encore en place aujourd''hui.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Le dernier livre d''entretiens a fait jaser, dans les ministères.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tu veux parler de celui où l''on évoque « l''ancien locataire de l''hôtel Matignon » ?</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">C''est bien ce volume-là.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Cette périphrase a, paraît-il, beaucoup amusé son destinataire.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Qui désigne au juste, en clair, cette belle périphrase ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Le président de la République actuellement en exercice.<break time="700ms"/>B.<break time="300ms"/>Le ministre des Affaires étrangères du gouvernement précédent.<break time="700ms"/>C.<break time="300ms"/>Un ancien Premier ministre français récemment quitté de ses fonctions.<break time="700ms"/>D.<break time="300ms"/>Le porte-parole habituel du gouvernement encore en place aujourd''hui.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Procédé : **périphrase**. L''hôtel Matignon est la résidence officielle du Premier ministre français ; « ancien locataire » indique qu''il en est sorti. La combinaison désigne donc un ex-chef du gouvernement. Seule C « ancien Premier ministre récemment quitté de ses fonctions » décode correctement la périphrase. A confond Matignon (Premier ministre) avec **l''Élysée** (président). B désigne **un autre membre du gouvernement**. D désigne **une fonction qui ne loge pas à Matignon**.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": true, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-DeniseNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.454459+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00c2-1000-0000-000000000014','B2','co_dialogue_c2_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Tu n''as cessé, hier, de répéter « moi, simple praticien, je m''en tiens aux faits ».
[Homme] J''ai voulu ramener le débat à la mesure.
[Femme] Mesure ou pose ? Tu maniais tes formules avec un certain art.
[Homme] On peut être à la fois lucide sur sa rhétorique et sincère, je crois.
[Femme] Quelle posture cherchais-tu, au juste, à incarner devant eux ?
[Homme] ...

A. Celle d''un orateur brillant, capable de tenir tête aux théoriciens.
B. Celle d''un débatteur agressif, prêt à pousser ses contradicteurs.
C. Celle d''un savant abstrait, soucieux de hauteur conceptuelle.
D. Celle de l''homme de terrain modeste, refusant les grandes théories.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tu n''as cessé, hier, de répéter « moi, simple praticien, je m''en tiens aux faits ».</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">J''ai voulu ramener le débat à la mesure.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Mesure ou pose ? Tu maniais tes formules avec un certain art.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">On peut être à la fois lucide sur sa rhétorique et sincère, je crois.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Quelle posture cherchais-tu, au juste, à incarner devant eux ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Celle d''un orateur brillant, capable de tenir tête aux théoriciens.<break time="700ms"/>B.<break time="300ms"/>Celle d''un débatteur agressif, prêt à pousser ses contradicteurs.<break time="700ms"/>C.<break time="300ms"/>Celle d''un savant abstrait, soucieux de hauteur conceptuelle.<break time="700ms"/>D.<break time="300ms"/>Celle de l''homme de terrain modeste, refusant les grandes théories.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Procédé : **posture rhétorique**. « Simple praticien », « je m''en tiens aux faits », « ramener à la mesure » construisent une figure d''humilité revendiquée qui s''oppose à la spéculation intellectuelle ; Denise relève l''art du procédé. Seule D « l''homme de terrain modeste, refusant les grandes théories » nomme cette posture. A propose **la posture inverse** (orateur brillant). B propose **une posture agressive**, démentie par « ramener à la mesure ». C propose **la posture spéculative**, précisément celle que Henri rejette.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": true, "display_order": 4}]','fr-FR-HenriNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.454459+02',NULL,NULL,NULL);
